      results[category] = {};

      for (const [metric, config] of Object.entries(metrics)) {
        const value = await this.measureMetric(metric);
        results[category][metric] = {
          value,
          threshold: config.threshold,
          unit: config.unit,
          status: value <= config.threshold ? "PASS" : "FAIL",
        };
      }
    }

    return results;
